CustomField.formula:
if (isblank (Start_Date__c), NULL,

(

if (Start_Date__c < date(2012,1,1), "CY" & right (text (year (Start_Date__c)), 2) &

(if (month (Start_Date__c) >= 10, "-Q4",
if (month (Start_Date__c) >= 7, "-Q3",
if (month (Start_Date__c) >= 4, "-Q2", "-Q1")))),


if (month (Start_Date__c) <= 3, "FY" & right (text (year (Start_Date__c)), 2) & "Q3", 
if (month (Start_Date__c) <= 6, "FY" & right (text (year (Start_Date__c)), 2) & "Q4", 
if (month (Start_Date__c) <= 9, "FY" & right (text (year (Start_Date__c)+1), 2) & "Q1", 
"FY" & right (text (year (Start_Date__c)+1), 2) & "Q2"))))))
